package com.overloadsync;

/** What the cue colours are applied to. */
public enum ColourTarget
{
	HIGHLIGHT("Highlight"),
	NUMBER("Number"),
	BOTH("Both");

	private final String label;

	ColourTarget(String label)
	{
		this.label = label;
	}

	boolean highlight()
	{
		return this != NUMBER;
	}

	boolean number()
	{
		return this != HIGHLIGHT;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.overloadsync;

/** How a cue colour is drawn on the item. */
public enum HighlightStyle
{
	BOX("Box"),
	OUTLINE("Outline"),
	FILL("Fill"),
	OUTLINE_AND_FILL("Outline and fill");

	private final String label;

	HighlightStyle(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.overloadsync;

/**
 * The two clocks that decide when to drink, in game ticks. Holds no game objects so it can be tested on its own.
 *
 * <ul>
 * <li>Stat decay: boosted combat stats drop by 1 on a background timer every 100 ticks (125 or 150 with
 * Preserve). All of these are multiples of 25, so only the decay tick modulo 25 matters here.</li>
 * <li>Overload: re-boosts every 25 ticks from the sip, 20 times (500 ticks), counted by a varbit that drops by 1
 * at each re-boost and reaches 0 when the overload wears off.</li>
 * </ul>
 *
 * Sipping so the first re-boost lands on a decay tick means no re-boost is ever late, so stats never dip a level.
 * Chain-potting on the expiry tick keeps that alignment, since 500 is a multiple of 25.
 */
class OverloadClock
{
	static final int REBOOST_TICKS = 25;

	/** Tick of the last observed decay, or -1 if not seen since logging in. */
	private int decayTick = -1;

	/** Re-boosts left (the varbit value). */
	private int reboostsLeft;

	/** Tick of the next re-boost, or -1 if not known yet (e.g. logged in mid-overload). */
	private int nextReboostTick = -1;

	void reset()
	{
		decayTick = -1;
		reboostsLeft = 0;
		nextReboostTick = -1;
	}

	/** A boosted combat stat dropped by exactly 1 on this tick. */
	void onDecay(int tick)
	{
		decayTick = tick;
	}

	/**
	 * The overload varbit changed.
	 *
	 * @return true if this was a fresh sip (the count went up)
	 */
	boolean onOverloadVarbit(int value, int tick)
	{
		boolean sip = value > reboostsLeft;
		if (value <= 0)
		{
			reboostsLeft = 0;
			nextReboostTick = -1;
			return false;
		}

		// A sip or a re-boost happens on this tick; the next one is 25 ticks later.
		nextReboostTick = tick + REBOOST_TICKS;
		reboostsLeft = value;
		return sip;
	}

	/** Called when the varbit is first read with an overload already running: the timing is unknown. */
	void onOverloadAlreadyActive(int value)
	{
		reboostsLeft = Math.max(0, value);
		nextReboostTick = -1;
	}

	boolean isDecayKnown()
	{
		return decayTick != -1;
	}

	boolean isOverloadActive()
	{
		return reboostsLeft > 0;
	}

	boolean isOverloadTimingKnown()
	{
		return reboostsLeft > 0 && nextReboostTick != -1;
	}

	/** Ticks until the overload wears off, or -1 if unknown. */
	int overloadTicksLeft(int tick)
	{
		if (!isOverloadTimingKnown())
		{
			return -1;
		}
		return Math.max(0, expiryTick() + 1 - tick); // counts to 0 on the tick the overload actually wears off
	}

	/** Ticks until the next re-boost (1 to 25), or -1 if unknown. */
	int ticksToReboost(int tick)
	{
		if (!isOverloadTimingKnown())
		{
			return -1;
		}
		return Math.max(0, nextReboostTick - tick);
	}

	/**
	 * Ticks until the tick to click an overload so it is drunk on a decay tick (0 = click now), or -1 if the
	 * decay clock has not been seen. Repeats every 25 ticks.
	 *
	 * @param adjust moves the cue later (+) or earlier (-) to match how clicks land in practice
	 */
	int ticksToAlignedClick(int tick, int adjust)
	{
		if (!isDecayKnown())
		{
			return -1;
		}
		// A click is carried out on the next game tick, and the game tick count only goes up after that tick's
		// events, so clicking when the count equals the decay tick lands the sip on the decay itself.
		return Math.floorMod(decayTick + adjust - tick, REBOOST_TICKS);
	}

	/**
	 * Ticks until the tick to click the next overload so it is drunk as the current one wears off (0 = click now),
	 * or -1 if unknown. Negative once that moment has passed.
	 */
	int ticksToChainClick(int tick, int adjust)
	{
		if (!isOverloadTimingKnown())
		{
			return -1;
		}
		return expiryTick() + adjust - tick; // same one-tick click delay as above
	}

	/**
	 * How many ticks after each decay the overload re-boosts, i.e. how long stats sit a level down. 0 is perfect: the
	 * re-boost lands on the decay tick itself and stats never dip. -1 if either clock is unknown.
	 */
	int ticksDownPerDecay()
	{
		if (!isDecayKnown() || !isOverloadTimingKnown())
		{
			return -1;
		}
		return Math.floorMod(nextReboostTick - decayTick, REBOOST_TICKS);
	}

	private int expiryTick()
	{
		return nextReboostTick + (reboostsLeft - 1) * REBOOST_TICKS;
	}
}

package com.overloadsync;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(OverloadSyncConfig.GROUP)
public interface OverloadSyncConfig extends Config
{
	String GROUP = "overloadsync";

	@ConfigSection(
		name = "Overload",
		description = "Countdowns on your overloads",
		position = 0
	)
	String overloadSection = "overload";

	@ConfigSection(
		name = "Brews",
		description = "Countdown to the next re-boost on your Xeric's aids and Saradomin brews",
		position = 1
	)
	String brewSection = "brew";

	@ConfigSection(
		name = "Timing",
		description = "Fine-tune when the overload cues show",
		position = 4,
		closedByDefault = true
	)
	String timingSection = "timing";

	@ConfigItem(
		keyName = "showSipCountdown",
		name = "Countdown to lined-up sip",
		description = "With no overload running, count down to the tick to click an overload so it re-boosts<br>"
			+ "on the same tick your stats decay, so they never dip. Comes round every 25 ticks.<br>"
			+ "Needs a boosted combat stat to have dropped by 1 since you logged in (shows ? until then).",
		section = overloadSection,
		position = 0
	)
	default boolean showSipCountdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTimeLeft",
		name = "Ticks left while active",
		description = "While an overload is running, show the ticks until it wears off",
		section = overloadSection,
		position = 1
	)
	default boolean showTimeLeft()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showChainCue",
		name = "Chain-pot cue",
		description = "Highlight your overloads on the tick to click so the next dose is drunk as the current one<br>"
			+ "wears off, keeping the 50 hitpoint heal and the lined-up timing",
		section = overloadSection,
		position = 2
	)
	default boolean showChainCue()
	{
		return true;
	}

	@Range(min = 1, max = 24)
	@Units(Units.TICKS)
	@ConfigItem(
		keyName = "overloadWindow",
		name = "Countdown window",
		description = "Colour your overloads this many ticks before the tick to click:<br>"
			+ "window colour, then get-ready colour, then click-now colour on the tick itself",
		section = overloadSection,
		position = 3
	)
	default int overloadWindow()
	{
		return 6;
	}

	@ConfigItem(
		keyName = "sipFeedback",
		name = "Sip feedback in chat",
		description = "After each overload sip, say in chat how well it lined up with the decay clock",
		section = overloadSection,
		position = 4
	)
	default boolean sipFeedback()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBrewCountdown",
		name = "Countdown to re-boost",
		description = "While an overload is running, show the ticks until its next re-boost on your Xeric's aids<br>"
			+ "and Saradomin brews",
		section = brewSection,
		position = 0
	)
	default boolean showBrewCountdown()
	{
		return true;
	}

	@Range(min = 1, max = 24)
	@Units(Units.TICKS)
	@ConfigItem(
		keyName = "brewWindowTicks",
		name = "Brew window",
		description = "Colour your brews this many ticks before the re-boost (shown as 0):<br>"
			+ "window colour, then get-ready colour, then click-now colour on the re-boost tick.<br>"
			+ "Potions are 3 ticks apart: clicking on 6 and 3 fits two sips before the re-boost.<br>"
			+ "At 24 the countdown is coloured the whole time.",
		section = brewSection,
		position = 1
	)
	default int brewWindow()
	{
		return 24;
	}

	@ConfigItem(
		keyName = "brewOnlyBelowHp",
		name = "Only when HP is low",
		description = "Only show the brew countdown while your hitpoints are at or below the level set below.<br>"
			+ "An overload heals 50 when it wears off, so brewing while high just wastes the heal.",
		section = brewSection,
		position = 2
	)
	default boolean brewOnlyBelowHp()
	{
		return false;
	}

	@Range(min = 1, max = 99)
	@ConfigItem(
		keyName = "brewHpThreshold",
		name = "At or below HP",
		description = "Show the brew countdown while your hitpoints are at or below this",
		section = brewSection,
		position = 3
	)
	default int brewHpThreshold()
	{
		return 49;
	}

	@ConfigSection(
		name = "Perfect timing",
		description = "Chat message and a subtle ding when you land a perfectly timed overload or brew",
		position = 5
	)
	String perfectSection = "perfect";

	@ConfigItem(
		keyName = "brewFeedback",
		name = "Perfect brew message",
		description = "Say in chat when a brew or Xeric's aid is drunk on the re-boost (clicked on the 0).<br>"
			+ "The ding has its own setting below.",
		section = perfectSection,
		position = 0
	)
	default boolean brewFeedback()
	{
		return true;
	}

	@ConfigItem(
		keyName = "perfectSound",
		name = "Ding on perfect timing",
		description = "A short, quiet ding for a perfectly timed overload or brew",
		section = perfectSection,
		position = 1
	)
	default boolean perfectSound()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "soundVolume",
		name = "Ding volume",
		description = "Volume of the ding, 0 to 100%. 0 is silent.",
		section = perfectSection,
		position = 2
	)
	default int soundVolume()
	{
		return 25;
	}

	@ConfigSection(
		name = "Reminders",
		description = "Pulse overloads and prayer enhances when their effect isn't running",
		position = 2
	)
	String reminderSection = "reminders";

	@ConfigItem(
		keyName = "pulseInactive",
		name = "Pulse when not active",
		description = "A pulsing box around your overloads and prayer enhances while their effect isn't running,<br>"
			+ "so you don't forget to drink them",
		section = reminderSection,
		position = 0
	)
	default boolean pulseInactive()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pulseColour",
		name = "Pulse colour",
		description = "Colour of the pulsing box",
		section = reminderSection,
		position = 1
	)
	default Color pulseColor()
	{
		return new Color(0, 255, 0);
	}

	@ConfigSection(
		name = "Appearance",
		description = "Highlight style, colours, font and number position",
		position = 3
	)
	String styleSection = "style";

	@ConfigItem(
		keyName = "highlightStyle",
		name = "Highlight style",
		description = "Box: shades the inventory slot. Outline: a line around the potion.<br>"
			+ "Fill: tints the potion itself.",
		section = styleSection,
		position = 0
	)
	default HighlightStyle highlightStyle()
	{
		return HighlightStyle.BOX;
	}

	@ConfigItem(
		keyName = "colourTarget",
		name = "Colour the",
		description = "Apply the countdown colours to the highlight, the number, or both",
		section = styleSection,
		position = 1
	)
	default ColourTarget colourTarget()
	{
		return ColourTarget.NUMBER;
	}

	@Alpha
	@ConfigItem(
		keyName = "windowColour",
		name = "Window colour",
		description = "Colour while inside the countdown window",
		section = styleSection,
		position = 2
	)
	default Color windowColor()
	{
		return new Color(255, 0, 0, 64);
	}

	@Range(min = 0, max = 10)
	@Units(Units.TICKS)
	@ConfigItem(
		keyName = "getReadyTicks",
		name = "Get ready ticks",
		description = "The last ticks of the window shown in the get-ready colour",
		section = styleSection,
		position = 3
	)
	default int getReadyTicks()
	{
		return 3;
	}

	@Alpha
	@ConfigItem(
		keyName = "getReadyColour",
		name = "Get ready colour",
		description = "Colour in the last ticks before the click",
		section = styleSection,
		position = 4
	)
	default Color soonColor()
	{
		return new Color(255, 170, 0, 64);
	}

	@Alpha
	@ConfigItem(
		keyName = "clickNowColour",
		name = "Click now colour",
		description = "Colour on the tick itself (0)",
		section = styleSection,
		position = 5
	)
	default Color readyColor()
	{
		return new Color(0, 255, 0, 128);
	}

	@ConfigItem(
		keyName = "textFont",
		name = "Number font",
		description = "Font of the countdown numbers",
		section = styleSection,
		position = 6
	)
	default TextFont textFont()
	{
		return TextFont.SMALL;
	}

	@ConfigItem(
		keyName = "textColor",
		name = "Number colour",
		description = "Colour of the countdown numbers when they are not coloured by the countdown",
		section = styleSection,
		position = 7
	)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "overloadTextPosition",
		name = "Overload number position",
		description = "Where the countdown sits on overloads",
		section = styleSection,
		position = 8
	)
	default TextPosition overloadTextPosition()
	{
		return TextPosition.BOTTOM_RIGHT;
	}

	@ConfigItem(
		keyName = "brewTextPosition",
		name = "Brew number position",
		description = "Where the countdown sits on brews",
		section = styleSection,
		position = 9
	)
	default TextPosition brewTextPosition()
	{
		return TextPosition.BOTTOM_RIGHT;
	}

	@Range(min = -2, max = 2)
	@Units(Units.TICKS)
	@ConfigItem(
		keyName = "clickAdjust",
		name = "Click timing adjust",
		description = "Moves the overload cues later (+) or earlier (-). Leave at 0 unless the chat feedback after<br>"
			+ "a sip on the cue keeps saying it was early or late.",
		section = timingSection,
		position = 0
	)
	default int clickAdjust()
	{
		return 0;
	}
}

package com.overloadsync;

import com.google.common.collect.ImmutableSet;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Draws the tick countdowns and highlights on overloads and brews in the inventory. */
class OverloadSyncOverlay extends WidgetItemOverlay
{
	static final Set<Integer> OVERLOADS = ImmutableSet.of(
		ItemID.RAIDS_VIAL_OVERLOAD_WEAK_1, ItemID.RAIDS_VIAL_OVERLOAD_WEAK_2,
		ItemID.RAIDS_VIAL_OVERLOAD_WEAK_3, ItemID.RAIDS_VIAL_OVERLOAD_WEAK_4,
		ItemID.RAIDS_VIAL_OVERLOAD_1, ItemID.RAIDS_VIAL_OVERLOAD_2,
		ItemID.RAIDS_VIAL_OVERLOAD_3, ItemID.RAIDS_VIAL_OVERLOAD_4,
		ItemID.RAIDS_VIAL_OVERLOAD_STRONG_1, ItemID.RAIDS_VIAL_OVERLOAD_STRONG_2,
		ItemID.RAIDS_VIAL_OVERLOAD_STRONG_3, ItemID.RAIDS_VIAL_OVERLOAD_STRONG_4);

	/** Xeric's aids (all strengths) and Saradomin brews. */
	static final Set<Integer> BREWS = ImmutableSet.of(
		ItemID.RAIDS_VIAL_XERICAID_WEAK_1, ItemID.RAIDS_VIAL_XERICAID_WEAK_2,
		ItemID.RAIDS_VIAL_XERICAID_WEAK_3, ItemID.RAIDS_VIAL_XERICAID_WEAK_4,
		ItemID.RAIDS_VIAL_XERICAID_1, ItemID.RAIDS_VIAL_XERICAID_2,
		ItemID.RAIDS_VIAL_XERICAID_3, ItemID.RAIDS_VIAL_XERICAID_4,
		ItemID.RAIDS_VIAL_XERICAID_STRONG_1, ItemID.RAIDS_VIAL_XERICAID_STRONG_2,
		ItemID.RAIDS_VIAL_XERICAID_STRONG_3, ItemID.RAIDS_VIAL_XERICAID_STRONG_4,
		ItemID._1DOSEPOTIONOFSARADOMIN, ItemID._2DOSEPOTIONOFSARADOMIN,
		ItemID._3DOSEPOTIONOFSARADOMIN, ItemID._4DOSEPOTIONOFSARADOMIN);

	static final Set<Integer> PRAYER_ENHANCES = ImmutableSet.of(
		ItemID.RAIDS_VIAL_PRAYER_WEAK_1, ItemID.RAIDS_VIAL_PRAYER_WEAK_2,
		ItemID.RAIDS_VIAL_PRAYER_WEAK_3, ItemID.RAIDS_VIAL_PRAYER_WEAK_4,
		ItemID.RAIDS_VIAL_PRAYER_1, ItemID.RAIDS_VIAL_PRAYER_2,
		ItemID.RAIDS_VIAL_PRAYER_3, ItemID.RAIDS_VIAL_PRAYER_4,
		ItemID.RAIDS_VIAL_PRAYER_STRONG_1, ItemID.RAIDS_VIAL_PRAYER_STRONG_2,
		ItemID.RAIDS_VIAL_PRAYER_STRONG_3, ItemID.RAIDS_VIAL_PRAYER_STRONG_4);

	/** One full pulse, in milliseconds. */
	private static final double PULSE_PERIOD_MS = 1200;

	private final Client client;
	private final OverloadSyncPlugin plugin;
	private final OverloadSyncConfig config;
	private final OverloadClock clock;
	private final ItemManager itemManager;

	@Inject
	OverloadSyncOverlay(Client client, OverloadSyncConfig config, OverloadSyncPlugin plugin, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.clock = plugin.getClock();
		this.plugin = plugin;
		this.itemManager = itemManager;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		Rectangle slot = widgetItem.getCanvasBounds();
		if (PRAYER_ENHANCES.contains(itemId))
		{
			if (config.pulseInactive() && !plugin.isPrayerEnhanceActive())
			{
				drawPulse(graphics, slot);
			}
			return;
		}

		Cue cue;
		TextPosition position;
		if (OVERLOADS.contains(itemId))
		{
			cue = overloadCue(client.getTickCount());
			position = config.overloadTextPosition();
		}
		else if (BREWS.contains(itemId))
		{
			cue = brewCue(client.getTickCount());
			position = config.brewTextPosition();
		}
		else
		{
			return;
		}

		boolean pulse = OVERLOADS.contains(itemId) && config.pulseInactive() && !clock.isOverloadActive();
		if (cue == null)
		{
			if (pulse)
			{
				drawPulse(graphics, slot);
			}
			return;
		}

		Rectangle bounds = slot;
		ColourTarget target = config.colourTarget();
		if (cue.color != null && target.highlight())
		{
			drawHighlight(graphics, itemId, widgetItem.getQuantity(), bounds, cue.color);
		}
		if (cue.text != null)
		{
			Color textColor = cue.color != null && target.number() ? solid(cue.color) : config.textColor();
			drawText(graphics, cue.text, bounds, position, textColor);
		}
		if (pulse)
		{
			drawPulse(graphics, bounds);
		}
	}

	/** A box around the slot that fades in and out. */
	void drawPulse(Graphics2D graphics, Rectangle bounds)
	{
		double phase = (System.currentTimeMillis() % (long) PULSE_PERIOD_MS) / PULSE_PERIOD_MS;
		int alpha = (int) Math.round(60 + 195 * (0.5 + 0.5 * Math.sin(phase * 2 * Math.PI)));
		Color c = config.pulseColor();
		graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha));
		graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
		graphics.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
	}

	/** Draws exactly one highlight in one colour, replacing nothing else on the item. */
	private void drawHighlight(Graphics2D graphics, int itemId, int quantity, Rectangle bounds, Color color)
	{
		HighlightStyle style = config.highlightStyle();
		Color solid = solid(color);
		if (style == HighlightStyle.BOX)
		{
			graphics.setColor(color);
			graphics.fill(bounds);
			graphics.setColor(solid);
			graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
			return;
		}

		if (style == HighlightStyle.FILL || style == HighlightStyle.OUTLINE_AND_FILL)
		{
			Image fill = fillImage(itemId, quantity, color);
			if (fill != null)
			{
				graphics.drawImage(fill, bounds.x, bounds.y, null);
			}
		}
		if (style == HighlightStyle.OUTLINE || style == HighlightStyle.OUTLINE_AND_FILL)
		{
			BufferedImage outline = itemManager.getItemOutline(itemId, quantity, solid);
			graphics.drawImage(outline, bounds.x, bounds.y, null);
		}
	}

	/** The item tinted in one colour. Small images, so made fresh each frame (no stale half-loaded copies). */
	private Image fillImage(int itemId, int quantity, Color color)
	{
		BufferedImage item = itemManager.getImage(itemId, quantity, false);
		return item == null ? null : ImageUtil.fillImage(item, color);
	}

	private static Color solid(Color c)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue());
	}

	private void drawText(Graphics2D graphics, String text, Rectangle bounds, TextPosition position, Color color)
	{
		graphics.setFont(config.textFont().font());
		FontMetrics metrics = graphics.getFontMetrics();
		int width = metrics.stringWidth(text);
		int ascent = metrics.getAscent();
		int x;
		int y;
		switch (position)
		{
			case TOP_LEFT:
				x = bounds.x + 1;
				y = bounds.y + ascent - 1;
				break;
			case TOP_RIGHT:
				x = bounds.x + bounds.width - width - 1;
				y = bounds.y + ascent - 1;
				break;
			case CENTRE:
				x = bounds.x + (bounds.width - width) / 2;
				y = bounds.y + (bounds.height + ascent) / 2 - 1;
				break;
			case BOTTOM_LEFT:
				x = bounds.x + 1;
				y = bounds.y + bounds.height - 1;
				break;
			case BOTTOM_RIGHT:
			default:
				x = bounds.x + bounds.width - width - 1;
				y = bounds.y + bounds.height - 1;
				break;
		}
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	Cue overloadCue(int tick)
	{
		int adjust = config.clickAdjust();
		if (clock.isOverloadActive())
		{
			if (!clock.isOverloadTimingKnown())
			{
				return null; // logged in mid-overload: known after its next re-boost
			}

			String text = config.showTimeLeft() ? String.valueOf(clock.overloadTicksLeft(tick)) : null;
			Color color = null;
			if (config.showChainCue())
			{
				int toClick = clock.ticksToChainClick(tick, adjust);
				color = cueColor(toClick, config.overloadWindow());
				if (text == null && color != null)
				{
					// Ticks left is hidden: count down to the click during the window instead.
					text = String.valueOf(toClick);
				}
			}
			return new Cue(text, color);
		}

		if (!config.showSipCountdown())
		{
			return null;
		}
		if (!clock.isDecayKnown())
		{
			return new Cue("?", null);
		}
		int toClick = clock.ticksToAlignedClick(tick, adjust);
		return new Cue(String.valueOf(toClick), cueColor(toClick, config.overloadWindow()));
	}

	Cue brewCue(int tick)
	{
		if (!config.showBrewCountdown() || !clock.isOverloadTimingKnown())
		{
			return null;
		}
		if (config.brewOnlyBelowHp() && client.getBoostedSkillLevel(Skill.HITPOINTS) > config.brewHpThreshold())
		{
			return null;
		}
		// 0 on the re-boost tick itself, then 24 down to 1.
		int toReboost = clock.ticksToReboost(tick) % OverloadClock.REBOOST_TICKS;
		return new Cue(String.valueOf(toReboost), cueColor(toReboost, config.brewWindow()));
	}

	/** Click-now colour at 0, get-ready colour for the last few ticks, window colour before that. */
	private Color cueColor(int ticks, int window)
	{
		if (ticks == 0)
		{
			return config.readyColor();
		}
		if (ticks < 0 || ticks > window)
		{
			return null;
		}
		return ticks <= config.getReadyTicks() ? config.soonColor() : config.windowColor();
	}

	/** What to draw on one item. */
	static final class Cue
	{
		final String text;
		final Color color;

		Cue(String text, Color color)
		{
			this.text = text;
			this.color = color;
		}
	}
}

package com.overloadsync;

import com.google.inject.Provides;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Overload Sync",
	description = "Tick countdowns on Chambers of Xeric overloads and brews: line your sip up with the stat decay clock and brew just before each re-boost",
	tags = {"cox", "raids", "chambers", "overload", "brew", "xeric", "boost", "tick"}
)
public class OverloadSyncPlugin extends Plugin
{
	/** The combat stats that boosts decay on. */
	private static final Skill[] DECAY_SKILLS = {Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private OverloadSyncOverlay overlay;

	@Inject
	private OverloadSyncConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private PerfectSound sound;

	private final OverloadClock clock = new OverloadClock();

	/** Last boosted level of each decay skill, or -1 if not read yet. */
	private final int[] lastLevels = new int[DECAY_SKILLS.length];

	/** True from logging in until the first game tick: varbits sent then are the current state, not a sip. */
	private boolean freshLogin;

	/** A prayer enhance lasts about 290 seconds; if the worn-off message is missed, assume it ended after this. */
	static final int PRAYER_ENHANCE_MAX_TICKS = 500;

	/** Tick the current prayer enhance is assumed to end by, or -1 if none is running. */
	private int prayerEnhanceUntilTick = -1;

	OverloadClock getClock()
	{
		return clock;
	}

	boolean isPrayerEnhanceActive()
	{
		return prayerEnhanceUntilTick != -1 && client.getTickCount() < prayerEnhanceUntilTick;
	}

	@Provides
	OverloadSyncConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OverloadSyncConfig.class);
	}

	@Override
	protected void startUp()
	{
		clock.reset();
		Arrays.fill(lastLevels, -1);
		freshLogin = false;
		prayerEnhanceUntilTick = -1;
		overlayManager.add(overlay);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				readLevels();
				clock.onOverloadAlreadyActive(client.getVarbitValue(VarbitID.RAIDS_OVERLOAD_TIMER));
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clock.reset();
		sound.close();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.LOGGING_IN)
		{
			// The decay clock restarts when you log in, so anything known before is stale.
			clock.reset();
			Arrays.fill(lastLevels, -1);
			freshLogin = true;
			prayerEnhanceUntilTick = -1;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (freshLogin)
		{
			freshLogin = false;
			readLevels();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		String lower = message.toLowerCase();
		if (lower.contains("prayer enhance"))
		{
			if (lower.startsWith("you drink"))
			{
				prayerEnhanceUntilTick = client.getTickCount() + PRAYER_ENHANCE_MAX_TICKS;
			}
			else if (lower.contains("worn off"))
			{
				prayerEnhanceUntilTick = -1;
			}
		}
		else if (lower.startsWith("you drink") && (lower.contains("xeric's aid") || lower.contains("saradomin brew")))
		{
			onBrewDrunk();
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Player local = client.getLocalPlayer();
		if (local != null && event.getActor() == local)
		{
			prayerEnhanceUntilTick = -1; // a prayer enhance ends on death
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.RAIDS_CLIENT_INDUNGEON)
		{
			if (event.getValue() == 0)
			{
				prayerEnhanceUntilTick = -1; // leaving a raid ends the effect
			}
			return;
		}
		if (event.getVarbitId() != VarbitID.RAIDS_OVERLOAD_TIMER)
		{
			return;
		}

		int value = event.getValue();
		if (freshLogin)
		{
			clock.onOverloadAlreadyActive(value);
			return;
		}

		if (clock.onOverloadVarbit(value, client.getTickCount()))
		{
			reportSip();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		int index = Arrays.asList(DECAY_SKILLS).indexOf(event.getSkill());
		if (index < 0)
		{
			return;
		}

		int last = lastLevels[index];
		int current = event.getBoostedLevel();
		lastLevels[index] = current;

		// A boosted stat dropping by exactly 1, without going below its real level, is the decay clock.
		// Brews and an overload wearing off drop by more than 1.
		if (last != -1 && current == last - 1 && current >= event.getLevel() && !freshLogin)
		{
			boolean first = !clock.isDecayKnown();
			clock.onDecay(client.getTickCount());
			if (first && config.sipFeedback())
			{
				int down = clock.ticksDownPerDecay();
				if (down == -1)
				{
					chat("Decay clock found: your overloads now count down to a perfectly timed sip.");
				}
				else if (down == 0)
				{
					chat("Decay clock found: your current overload is already perfectly timed.");
				}
				else
				{
					chat("Decay clock found: " + describeOffset(down) + " Chain-potting keeps this timing"
						+ " for the rest of the raid.");
				}
			}
		}
	}

	private void readLevels()
	{
		for (int i = 0; i < DECAY_SKILLS.length; i++)
		{
			lastLevels[i] = client.getBoostedSkillLevel(DECAY_SKILLS[i]);
		}
	}

	/** Plain-words version of how far a sip is from perfect (down = ticks after the decay that it re-boosts). */
	private static String describeOffset(int down)
	{
		if (down <= OverloadClock.REBOOST_TICKS / 2)
		{
			String hint = down <= 2 ? " If you clicked on the green cue, set Click timing adjust to -" + down + "." : "";
			return "your overload re-boosts " + down + (down == 1 ? " tick" : " ticks") + " after each decay, so stats"
				+ " dip a level for " + down + (down == 1 ? " tick" : " ticks") + " each time." + hint;
		}
		int early = OverloadClock.REBOOST_TICKS - down;
		String hint = early <= 2 ? " If you clicked on the green cue, set Click timing adjust to +" + early + "." : "";
		return "your overload is " + early + (early == 1 ? " tick" : " ticks") + " early: each re-boost lands just"
			+ " before a decay, so stats dip a level for " + down + " ticks each time." + hint;
	}

	private void reportSip()
	{
		int down = clock.ticksDownPerDecay();
		if (down == -1)
		{
			sipChat("Overload drunk before the decay clock was seen, so it could not be lined up. A boosted combat"
				+ " stat dropping by 1 (e.g. Defence after a Xeric's aid) sets the clock.");
		}
		else if (down == 0)
		{
			sipChat("Perfect overload timing: every re-boost lands on a decay tick, so your stats never dip a level.");
			ding();
		}
		else
		{
			sipChat("Overload not perfect: " + describeOffset(down));
		}
	}

	/** The chat line after a sip, unless sip feedback is off (the ding has its own setting). */
	private void sipChat(String message)
	{
		if (config.sipFeedback())
		{
			chat(message);
		}
	}

	/** A brew or Xeric's aid was drunk. Perfect when it lands on the re-boost game tick (clicked on the 0). */
	private void onBrewDrunk()
	{
		if (!clock.isOverloadTimingKnown())
		{
			return;
		}
		// Clicked on the 0, carried out on the re-boost game tick: the re-boost is either just counted (25 away) or
		// about to be (0 away) when this message arrives.
		if (clock.ticksToReboost(client.getTickCount()) % OverloadClock.REBOOST_TICKS == 0)
		{
			if (config.brewFeedback())
			{
				chat("Perfect brew timing: drunk on the re-boost, so the heal lands with your stats back at full boost.");
			}
			ding();
		}
	}

	private void ding()
	{
		if (config.perfectSound())
		{
			sound.ding(config.soundVolume());
		}
	}

	private void chat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("Overload Sync: " + message)
			.build());
	}
}

package com.overloadsync;

import java.io.ByteArrayInputStream;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.audio.AudioPlayer;

/** A short, soft two-note ding built in memory as a WAV, so there are no sound files. */
@Singleton
class PerfectSound
{
	private static final int SAMPLE_RATE = 44100;
	private static final byte[] WAV = build();

	private final AudioPlayer audioPlayer;
	private final ScheduledExecutorService executor;

	@Inject
	PerfectSound(AudioPlayer audioPlayer, ScheduledExecutorService executor)
	{
		this.audioPlayer = audioPlayer;
		this.executor = executor;
	}

	void ding(int volumePercent)
	{
		if (volumePercent <= 0)
		{
			return;
		}
		// Volume 100 is the full level of the ding (0 dB); lower values are quieter.
		float gain = (float) Math.max(-80.0, 20.0 * Math.log10(Math.min(100, volumePercent) / 100.0));
		executor.submit(() ->
		{
			try
			{
				audioPlayer.play(new ByteArrayInputStream(WAV), gain);
			}
			catch (Exception ignored)
			{
				// No audio device available: the chat message still shows.
			}
		});
	}

	void close()
	{
		// Nothing to release: the audio player closes each sound when it finishes.
	}

	/** Two notes (A5 then E6), each a quick decaying sine, as 16-bit mono PCM in a WAV container. */
	static byte[] build()
	{
		int[] freqs = {880, 1319};
		int noteSamples = (int) (SAMPLE_RATE * 0.14);
		int step = (int) (SAMPLE_RATE * 0.07);
		int total = step + noteSamples;
		double[] mix = new double[total];
		for (int n = 0; n < freqs.length; n++)
		{
			int start = n * step;
			for (int i = 0; i < noteSamples; i++)
			{
				double attack = Math.min(1.0, i / (SAMPLE_RATE * 0.004));
				double decay = Math.exp(-i / (SAMPLE_RATE * 0.045));
				mix[start + i] += Math.sin(2 * Math.PI * freqs[n] * i / SAMPLE_RATE) * attack * decay * 0.5;
			}
		}

		int dataBytes = total * 2;
		byte[] wav = new byte[44 + dataBytes];
		putAscii(wav, 0, "RIFF");
		putInt(wav, 4, 36 + dataBytes);
		putAscii(wav, 8, "WAVE");
		putAscii(wav, 12, "fmt ");
		putInt(wav, 16, 16);
		putShort(wav, 20, 1); // PCM
		putShort(wav, 22, 1); // mono
		putInt(wav, 24, SAMPLE_RATE);
		putInt(wav, 28, SAMPLE_RATE * 2);
		putShort(wav, 32, 2);
		putShort(wav, 34, 16);
		putAscii(wav, 36, "data");
		putInt(wav, 40, dataBytes);
		for (int i = 0; i < total; i++)
		{
			putShort(wav, 44 + 2 * i, (short) (Math.max(-1, Math.min(1, mix[i])) * Short.MAX_VALUE));
		}
		return wav;
	}

	private static void putAscii(byte[] b, int at, String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			b[at + i] = (byte) s.charAt(i);
		}
	}

	private static void putShort(byte[] b, int at, int v)
	{
		b[at] = (byte) (v & 0xff);
		b[at + 1] = (byte) ((v >> 8) & 0xff);
	}

	private static void putInt(byte[] b, int at, int v)
	{
		putShort(b, at, v & 0xffff);
		putShort(b, at + 2, (v >>> 16) & 0xffff);
	}
}

